CREATE TABLE accounts (id TEXT PRIMARY KEY, status TEXT NOT NULL CHECK(status IN ('active','suspended','deleting','deleted')), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE TABLE memberships (account_id TEXT NOT NULL REFERENCES accounts(id), actor_id TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('customer','account_admin')), status TEXT NOT NULL CHECK(status IN ('active','revoked')), PRIMARY KEY(account_id,actor_id));
CREATE TABLE deployments (account_id TEXT NOT NULL REFERENCES accounts(id), id TEXT NOT NULL, generation INTEGER NOT NULL CHECK(generation>0), state TEXT NOT NULL CHECK(state IN ('pending','ready','stopped','failed','deleting','deleted')), secret_binding_id TEXT, runtime_version TEXT, PRIMARY KEY(account_id,id));
CREATE TABLE projects (account_id TEXT NOT NULL REFERENCES accounts(id), id TEXT NOT NULL, name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 120), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(account_id,id));
CREATE TABLE conversations (account_id TEXT NOT NULL, project_id TEXT NOT NULL, id TEXT NOT NULL, deployment_id TEXT NOT NULL, native_session_ref TEXT, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(account_id,id), UNIQUE(account_id,project_id,id), FOREIGN KEY(account_id,project_id) REFERENCES projects(account_id,id), FOREIGN KEY(account_id,deployment_id) REFERENCES deployments(account_id,id));
CREATE TABLE tasks (account_id TEXT NOT NULL, project_id TEXT NOT NULL, conversation_id TEXT NOT NULL, id TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('queued','running','waiting_for_approval','paused','cancelled','failed','budget_exhausted','completed','blocked')), budget_microusd INTEGER NOT NULL CHECK(budget_microusd>=0), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(account_id,id), UNIQUE(account_id,project_id,id), FOREIGN KEY(account_id,project_id,conversation_id) REFERENCES conversations(account_id,project_id,id));
CREATE TABLE operations (account_id TEXT NOT NULL REFERENCES accounts(id), id TEXT NOT NULL, deployment_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('create','start','stop','upgrade','backup','restore','delete')), state TEXT NOT NULL CHECK(state IN ('pending','running','completed','failed','uncertain')), idempotency_key TEXT NOT NULL, request_hash TEXT NOT NULL, generation INTEGER NOT NULL CHECK(generation>0), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(account_id,id), UNIQUE(account_id,idempotency_key), FOREIGN KEY(account_id,deployment_id) REFERENCES deployments(account_id,id));
CREATE TABLE events (account_id TEXT NOT NULL, task_id TEXT NOT NULL, id TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence>0), kind TEXT NOT NULL, public_payload TEXT NOT NULL CHECK(json_valid(public_payload)), created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(account_id,id), UNIQUE(account_id,task_id,sequence), FOREIGN KEY(account_id,task_id) REFERENCES tasks(account_id,id));
CREATE TABLE artifacts (account_id TEXT NOT NULL, project_id TEXT NOT NULL, task_id TEXT NOT NULL, id TEXT NOT NULL, version INTEGER NOT NULL CHECK(version>0), display_name TEXT NOT NULL, media_type TEXT NOT NULL, size_bytes INTEGER NOT NULL CHECK(size_bytes>=0), sha256 TEXT NOT NULL CHECK(length(sha256)=64), storage_ref TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(account_id,id,version), FOREIGN KEY(account_id,project_id,task_id) REFERENCES tasks(account_id,project_id,id));
CREATE TABLE usage_entries (account_id TEXT NOT NULL, task_id TEXT NOT NULL, id TEXT NOT NULL, provider TEXT NOT NULL, provider_request_id TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('reserved','estimated','reported','reconciled','adjusted','released')), amount_microusd INTEGER NOT NULL, currency TEXT NOT NULL CHECK(currency='USD'), price_version TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(account_id,id), UNIQUE(account_id,provider,provider_request_id,kind), FOREIGN KEY(account_id,task_id) REFERENCES tasks(account_id,id));
CREATE TABLE entitlements (account_id TEXT NOT NULL REFERENCES accounts(id), id TEXT NOT NULL, plan_version TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('trial','active','grace','expired','suspended')), limits_json TEXT NOT NULL CHECK(json_valid(limits_json)), valid_until TEXT NOT NULL, PRIMARY KEY(account_id,id));
CREATE TABLE audit_events (account_id TEXT NOT NULL REFERENCES accounts(id), id TEXT NOT NULL, actor_id TEXT NOT NULL, object_id TEXT NOT NULL, action TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('pending','completed','denied','failed','uncertain')), request_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')), PRIMARY KEY(account_id,id));
CREATE INDEX tasks_account_state ON tasks(account_id,state);
CREATE INDEX events_account_task ON events(account_id,task_id,sequence);
CREATE INDEX usage_account_task ON usage_entries(account_id,task_id,created_at);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'audit is append only'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'audit is append only'); END;
CREATE TRIGGER usage_no_update BEFORE UPDATE ON usage_entries BEGIN SELECT RAISE(ABORT,'usage is append only'); END;
CREATE TRIGGER usage_no_delete BEFORE DELETE ON usage_entries BEGIN SELECT RAISE(ABORT,'usage is append only'); END;
